pragma solidity ^0.8.10;

/// @title IPythLazer
/// @notice Interface for the Pyth Lazer contract
interface IPythLazer {
    /// @notice Gets the verification fee required to verify an update
    /// @return The verification fee in wei
    function verification_fee() external view returns (uint256);

    /// @notice Verifies a price update from Pyth Lazer
    /// @param update The encoded update data
    /// @return payload The verified payload data
    /// @return signer The address of the signer
    function verifyUpdate(bytes calldata update) external payable returns (bytes calldata payload, address signer);
}

